CREATE TABLE ccv_aggregation_jobs
(
    id             BIGSERIAL   PRIMARY KEY,
    job_id         UUID        UNIQUE NOT NULL,
    owner_id       TEXT        NOT NULL,
    dedup_key      TEXT        NOT NULL,
    task_data      JSONB       NOT NULL,
    status         TEXT        NOT NULL DEFAULT 'pending',
    created_at     TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    available_at   TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    started_at     TIMESTAMPTZ,
    attempt_count  INT         NOT NULL DEFAULT 0,
    retry_deadline TIMESTAMPTZ NOT NULL,
    last_error     TEXT,
    CONSTRAINT ccv_aggregation_jobs_status_check CHECK (status IN ('pending', 'processing', 'completed', 'failed'))
);

CREATE UNIQUE INDEX ccv_aggregation_jobs_unique_job
    ON ccv_aggregation_jobs (owner_id, dedup_key) WHERE status = 'pending';

CREATE INDEX idx_ccv_aggregation_jobs_consume
    ON ccv_aggregation_jobs (owner_id, available_at ASC, id ASC) WHERE status = 'pending';

CREATE INDEX idx_ccv_aggregation_jobs_stale
    ON ccv_aggregation_jobs (owner_id, started_at ASC, id ASC) WHERE status = 'processing' AND started_at IS NOT NULL;

CREATE INDEX idx_ccv_aggregation_jobs_status
    ON ccv_aggregation_jobs (owner_id, status);

CREATE TABLE ccv_aggregation_jobs_archive
(
    id             BIGINT      PRIMARY KEY,
    job_id         UUID        UNIQUE NOT NULL,
    owner_id       TEXT        NOT NULL,
    dedup_key      TEXT        NOT NULL,
    task_data      JSONB       NOT NULL,
    status         TEXT        NOT NULL,
    created_at     TIMESTAMPTZ NOT NULL,
    available_at   TIMESTAMPTZ NOT NULL,
    started_at     TIMESTAMPTZ,
    attempt_count  INT         NOT NULL,
    retry_deadline TIMESTAMPTZ NOT NULL,
    last_error     TEXT,
    completed_at   TIMESTAMPTZ NOT NULL
);

CREATE INDEX idx_ccv_aggregation_jobs_archive_completed
    ON ccv_aggregation_jobs_archive (owner_id, completed_at DESC);

CREATE INDEX idx_ccv_aggregation_jobs_archive_dedup_key
    ON ccv_aggregation_jobs_archive (dedup_key);

